+import { $internal } from '../common';
+import type { Schema } from '../storage';
+import type { Trait, TraitRecord, TraitValue } from './types';
+
+export const $aspect = Symbol('aspect');
+
+export type AspectInput = Trait | Aspect;
+export type Aspect<TTraits extends readonly AspectInput[] = readonly AspectInput[]> = {
+    readonly [$aspect]: true;
+    readonly id: number;
+    readonly traits: readonly Trait[];
+    readonly schema: Schema;
+} & ((params?: Partial<AspectRecord<TTraits>>) => [Aspect<TTraits>, Partial<AspectRecord<TTraits>>]);
+
+export type AspectRecord<TTraits extends readonly AspectInput[]> = UnionToIntersection<
+    TraitRecordOf<TTraits[number]>
+>;
+
+type TraitRecordOf<T> = T extends Aspect<infer TTraits>
+    ? AspectRecord<TTraits>
+    : T extends Trait
+      ? TraitRecord<T>
+      : never;
+
+type UnionToIntersection<T> = (T extends unknown ? (value: T) => void : never) extends (
+    value: infer I
+) => void
+    ? I
+    : never;
+
+let aspectId = 0;
+
+export function isAspect(value: unknown): value is Aspect {
+    return Boolean((value as Aspect | null | undefined)?.[$aspect]);
+}
+
+/** Creates a composite view over two or more non-relation traits. */
+export function createAspect<T extends readonly [AspectInput, AspectInput, ...AspectInput[]]>(
+    ...inputs: T
+): Aspect<T> {
+    const traits: Trait[] = [];
+    const fields = new Set<string>();
+    const schema: Record<string, unknown> = {};
+
+    for (const input of inputs) {
+        const constituents = isAspect(input) ? input.traits : [input];
+        for (const trait of constituents) {
+            if (trait[$internal].relation) {
+                throw new Error('Koota: Relations cannot be constituents of an aspect.');
+            }
+            for (const field of Object.keys(trait.schema)) {
+                if (fields.has(field)) {
+                    throw new Error(`Koota: Aspect traits overlap on field "${field}".`);
+                }
+                fields.add(field);
+                schema[field] = trait.schema[field as keyof typeof trait.schema];
+            }
+            traits.push(trait);
+        }
+    }
+
+    const id = aspectId++;
+    const aspect = Object.assign(
+        (params: Partial<AspectRecord<T>> = {}) => [aspect, params] as const,
+        { [$aspect]: true as const, id, traits: Object.freeze(traits), schema: Object.freeze(schema) }
+    ) as Aspect<T>;
+
+    return Object.freeze(aspect);
+}
+
+export function getAspectTraits(input: Trait | Aspect): readonly Trait[] {
+    return isAspect(input) ? input.traits : [input];
+}
+
+export function getAspectValue(
+    get: (trait: Trait) => TraitRecord<Trait> | undefined,
+    aspect: Aspect
+): Record<string, unknown> | undefined {
+    const value: Record<string, unknown> = {};
+    for (const trait of aspect.traits) {
+        const data = get(trait);
+        if (data === undefined) return undefined;
+        Object.assign(value, data);
+    }
+    return value;
+}
+
+export function getAspectTraitValue(trait: Trait, value: Record<string, unknown>): TraitValue<any> {
+    if (trait[$internal].type === 'aos') return value;
+    const result: Record<string, unknown> = {};
+    for (const field of Object.keys(trait.schema)) {
+        if (field in value) result[field] = value[field];
+    }
+    return result;
+}
